<template>
    <div>
        <Head title="Mans profils" />
        <div class="row">
            <div class="md:col-8">
                <Card title="Personas dati" icon="person" card-header-class="card-header-primary">
                    <form @submit.prevent="saveProfile">
                        <div class="form-group">
                            <label for="profile-name">Vārds</label>
                            <input id="profile-name" v-model="profileForm.name" type="text" class="form-control" autocomplete="name" required :disabled="profileForm.processing">
                            <InputError :message="profileForm.errors.name" />
                        </div>
                        <div class="form-group">
                            <label for="profile-email">E-pasta adrese</label>
                            <input id="profile-email" v-model="profileForm.email" type="email" class="form-control" autocomplete="email" required :disabled="profileForm.processing">
                            <InputError :message="profileForm.errors.email" />
                        </div>
                        <p class="fg-2">Mainot e-pasta adresi, tā būs jāapstiprina vēlreiz.</p>
                        <button type="submit" class="btn btn-primary" :disabled="profileForm.processing">
                            {{ profileForm.processing ? 'Saglabā…' : 'Saglabāt izmaiņas' }}
                        </button>
                        <p v-if="profileForm.recentlySuccessful" class="text-success" role="status">Profils atjaunots.</p>
                    </form>
                    <div v-if="mustVerifyEmail && !user.email_verified_at" class="mt-3">
                        <p class="text-warning">Jūsu e-pasta adrese vēl nav apstiprināta.</p>
                        <Form v-bind="verificationForm" v-slot="{ processing }">
                            <button type="submit" class="btn btn-primary btn-sm" :disabled="processing">Nosūtīt apstiprinājuma saiti</button>
                        </Form>
                        <p v-if="status === 'verification-link-sent'" class="text-success" role="status">Apstiprinājuma saite nosūtīta.</p>
                    </div>
                </Card>
            </div>
            <div class="md:col-4">
                <Card title="Profila attēls" icon="photo_camera" card-header-class="card-header-rose">
                    <form class="text-center" @submit.prevent="saveAvatar">
                        <div v-if="!avatarForm.avatar && !user.avatar_url" class="profile-avatar-fallback mx-auto" aria-hidden="true">
                            <i class="material-icons">person</i>
                        </div>
                        <ImagePicker v-model="avatarForm.avatar" :placeholder="user.avatar_url || ''" avatar crop label="Izvēlēties attēlu" accept="image/*" :disabled="avatarBusy" />
                        <p class="fg-2 mt-2">Izvēlieties attēlu un pielāgojiet izmēru un novietojumu. Augšupielādēsim tikai sagatavoto 512 × 512 attēlu.</p>
                        <InputError :message="avatarForm.errors.avatar" />
                        <button type="submit" class="btn btn-primary" :disabled="!avatarForm.avatar || avatarBusy">
                            {{ avatarForm.processing ? 'Augšupielādē…' : 'Saglabāt attēlu' }}
                        </button>
                        <progress v-if="avatarForm.progress" class="w-100" :value="avatarForm.progress.percentage" max="100" aria-label="Attēla augšupielāde"></progress>
                    </form>
                    <form v-if="user.avatar_url" class="text-center" @submit.prevent="removeAvatar">
                        <button type="submit" class="btn btn-link btn-danger" :disabled="avatarBusy">Dzēst saglabāto attēlu</button>
                    </form>
                </Card>
            </div>
        </div>
    </div>
</template>

<script>
import { Form, Head, useForm } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';
import ImagePicker from '@scaffold/components/ImagePicker.vue';
import InputError from '@scaffold/components/InputError.vue';
import { update as updateProfile } from '@app/routes/profile';
import { update as updateAvatar, destroy as destroyAvatar } from '@app/routes/avatars';
import { send } from '@app/routes/verification';

export default {
    name: 'ProfileSettings',
    components: { Card, Form, Head, ImagePicker, InputError },
    layout: { pageTitle: 'Mans profils' },
    props: { mustVerifyEmail: Boolean, status: String },
    data() {
        const user = this.$page.props.auth.user;
        return {
            profileForm: useForm({ name: user.name, email: user.email }),
            avatarForm: useForm({ avatar: null }),
            removeAvatarForm: useForm({}),
            verificationForm: send.form(),
        };
    },
    computed: {
        user() {
            return this.$page.props.auth.user;
        },
        avatarBusy() {
            return this.avatarForm.processing || this.removeAvatarForm.processing;
        },
    },
    methods: {
        saveProfile() {
            this.profileForm.patch(updateProfile.url(), {
                preserveScroll: true,
                onSuccess: () => {
                    this.profileForm.defaults({ name: this.user.name, email: this.user.email });
                    this.profileForm.reset();
                },
            });
        },
        saveAvatar() {
            if (!this.avatarForm.avatar || this.avatarBusy) {
                return;
            }
            this.avatarForm.post(updateAvatar.url(), {
                forceFormData: true,
                preserveScroll: true,
                onSuccess: () => this.avatarForm.reset(),
            });
        },
        removeAvatar() {
            if (this.avatarBusy) {
                return;
            }
            this.removeAvatarForm.delete(destroyAvatar.url(), {
                preserveScroll: true,
                onSuccess: () => this.avatarForm.reset(),
            });
        },
    },
};
</script>

<style scoped>
.profile-avatar-fallback {
    display: grid;
    place-items: center;
    width: 8rem;
    height: 8rem;
    border-radius: 50%;
    background: var(--bg-3);
    color: var(--fg-2);
}

.profile-avatar-fallback .material-icons {
    font-size: 4rem;
}
</style>
